import React from 'react';

const Settings = ({ onBack, settings, onUpdate }) => {
  const languages = [
    { id: 'PT-PT', label: 'Português (EU)' },
    { id: 'EN', label: 'English' },
    { id: 'ES', label: 'Español' },
    { id: 'FR', label: 'Français' },
    { id: 'DE', label: 'Deutsch' }
  ];

  return (
    <div className="min-h-screen bg-raw-onyx text-raw-bone p-8 flex flex-col items-center select-none">
      <div className="max-w-2xl w-full pt-12">
        <div className="flex justify-between items-end mb-16 border-b border-raw-bone/10 pb-8">
          <h1 className="text-7xl font-archivo tracking-tighter">
            CONFIG<span className="text-raw-cyan">.</span>
          </h1>
          <button 
            onClick={onBack} 
            className="text-[10px] uppercase tracking-[0.3em] text-raw-cyan hover:brightness-125 transition-all mb-2 font-bold"
          >
            [ Fechar ]
          </button>
        </div>

        <div className="space-y-16">
          {/* SELEÇÃO DE IDIOMA */}
          <section>
            <h2 className="text-[10px] uppercase tracking-[0.5em] text-raw-bone/30 mb-8">
              Linguagem do Sistema
            </h2>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              {languages.map((lang) => (
                <button
                  key={lang.id}
                  onClick={() => onUpdate('language', lang.id)}
                  className={`p-5 border-2 transition-all text-left uppercase font-archivo text-xs tracking-[0.2em] ${
                    settings.language === lang.id 
                    ? 'border-raw-cyan text-raw-cyan bg-raw-cyan/5 shadow-[0_0_15px_rgba(0,240,255,0.1)]' 
                    : 'border-raw-bone/5 text-raw-bone/30 hover:border-raw-bone/20'
                  }`}
                >
                  {lang.label}
                  {settings.language === lang.id && <span className="float-right text-[8px] mt-1">●</span>}
                </button>
              ))}
            </div>
          </section>

          {/* PREFERÊNCIAS VISUAIS */}
          <section>
            <h2 className="text-[10px] uppercase tracking-[0.5em] text-raw-bone/30 mb-8 border-b border-raw-bone/5 pb-2">
              Performance & Visual
            </h2>
            <div className="flex justify-between items-center group cursor-pointer" onClick={() => onUpdate('animations', !settings.animations)}>
              <div>
                <h3 className="font-archivo text-xl uppercase tracking-tight">Animações de Interface</h3>
                <p className="text-[10px] text-raw-bone/40 uppercase mt-1 tracking-widest">Efeitos de fade e slide entre menus</p>
              </div>
              <div className={`w-14 h-7 border-2 flex items-center px-1 transition-all duration-300 ${
                settings.animations ? 'border-raw-cyan bg-raw-cyan/10' : 'border-raw-bone/20'
              }`}>
                <div className={`w-4 h-4 transition-all duration-300 ${
                  settings.animations ? 'bg-raw-cyan translate-x-7' : 'bg-raw-bone/20 translate-x-0'
                }`} />
              </div>
            </div>
          </section>
        </div>
      </div>
    </div>
  );
};

export default Settings;
